  <script>
    const featuredCoins = [
      { rank: 1, name: 'Bitcoin', symbol: 'BTC', price: 75612.78, h1: 0.21, h24: 1.15, d7: 4.97, mcap: 1.51e12, vol: 2.8435e11, supply: '20.01M BTC', network: 'Ethereum', category: 'Top' },
      { rank: 2, name: 'Ethereum', symbol: 'ETH', price: 2356.00, h1: 0.11, h24: 0.94, d7: 3.66, mcap: 2.83e11, vol: 1.219e11, supply: '120.12M ETH', network: 'Ethereum', category: 'Top' },
      { rank: 3, name: 'Tether', symbol: 'USDT', price: 1.00, h1: 0.00, h24: 0.01, d7: 0.03, mcap: 1.09e11, vol: 8.994e10, supply: '109.01B USDT', network: 'BSC', category: 'Top' },
      { rank: 4, name: 'BNB', symbol: 'BNB', price: 612.44, h1: -0.05, h24: 0.84, d7: 2.41, mcap: 8.91e10, vol: 3.18e9, supply: '145.89M BNB', network: 'BSC', category: 'Top' },
      { rank: 5, name: 'Solana', symbol: 'SOL', price: 88.25, h1: 0.52, h24: 2.14, d7: 7.23, mcap: 4.03e10, vol: 3.91e9, supply: '456.02M SOL', network: 'Solana', category: 'Trending' }
    ];

    const categories = ['Top', 'Trending', 'Watchlist', 'Prediction Markets', 'Most Visited', 'New'];
    const networks = ['Ethereum', 'BSC', 'Solana', 'Base'];
    const allCoins = [];

    function seededValue(seed, min, max, decimals = 2) {
      const value = min + (Math.sin(seed * 91.217) + 1) / 2 * (max - min);
      return Number(value.toFixed(decimals));
    }

    for (let i = 1; i <= 100; i++) {
      if (i <= featuredCoins.length) {
        allCoins.push(featuredCoins[i - 1]);
      } else {
        const sym = `C${i}`;
        allCoins.push({
          rank: i,
          name: `Coin ${i}`,
          symbol: sym,
          price: seededValue(i, 0.12, 950),
          h1: seededValue(i + 1, -2.4, 2.4),
          h24: seededValue(i + 2, -8.5, 9.2),
          d7: seededValue(i + 3, -18.5, 21.8),
          mcap: seededValue(i + 4, 9e7, 7e10, 0),
          vol: seededValue(i + 5, 2e6, 2.5e10, 0),
          supply: `${seededValue(i + 6, 10, 900, 2)}M ${sym}`,
          network: networks[i % networks.length],
          category: categories[i % categories.length]
        });
      }
    }

    const tbody = document.querySelector('#cryptoTable tbody');
    const pagination = document.getElementById('pagination');
    const categoryTabs = document.getElementById('categoryTabs');
    const networkTabs = document.getElementById('networkTabs');
    const activeCategoryLabel = document.getElementById('activeCategoryLabel');
    const activeNetworkLabel = document.getElementById('activeNetworkLabel');

    let activeCategory = 'Top';
    let activeNetwork = 'All Networks';
    let activePage = 1;
    const totalPages = 84;

    function money(n) {
      return '$' + Number(n).toLocaleString(undefined, { maximumFractionDigits: 2, minimumFractionDigits: 2 });
    }

    function shortMoney(n) {
      if (n >= 1e12) return '$' + (n / 1e12).toFixed(2) + 'T';
      if (n >= 1e9) return '$' + (n / 1e9).toFixed(2) + 'B';
      if (n >= 1e6) return '$' + (n / 1e6).toFixed(2) + 'M';
      return money(n);
    }

    function sparkPath(change) {
      const up = change >= 0;
      return up
        ? 'M2 18 L10 14 L18 15 L26 10 L34 11 L42 7 L50 8 L58 5'
        : 'M2 5 L10 8 L18 7 L26 10 L34 11 L42 14 L50 13 L58 18';
    }

    function pctClass(v) { return v >= 0 ? 'pos' : 'neg'; }
    function fmtPct(v) { return `${v >= 0 ? '+' : ''}${v.toFixed(2)}%`; }

    function getFilteredData() {
      return allCoins.filter(c => {
        const categoryOk = activeCategory === 'Top' ? true : c.category === activeCategory;
        const networkOk = activeNetwork === 'All Networks' || activeNetwork === 'More' ? true : c.network === activeNetwork;
        return categoryOk && networkOk;
      });
    }

    function renderTable() {
      const data = getFilteredData();
      tbody.innerHTML = data.map(c => {
        const logoHue = (c.rank * 37) % 360;
        return `
          <tr>
            <td class="rank mono">${c.rank}</td>
            <td class="coin-cell">
              <div class="coin-main">
                <span class="coin-logo" style="background:hsl(${logoHue} 56% 45%)">${c.symbol.slice(0,1)}</span>
                <span><span class="coin-name">${c.name}</span><span class="coin-symbol">${c.symbol}</span></span>
              </div>
            </td>
            <td class="num mono">${money(c.price)}</td>
            <td class="pct ${pctClass(c.h1)} col-h1">${fmtPct(c.h1)}</td>
            <td class="pct ${pctClass(c.h24)} col-h24">${fmtPct(c.h24)}</td>
            <td class="pct ${pctClass(c.d7)} col-d7">${fmtPct(c.d7)}</td>
            <td class="num mono col-mcap">${shortMoney(c.mcap)}</td>
            <td class="num mono col-vol">${shortMoney(c.vol)}</td>
            <td class="num mono col-supply">${c.supply}</td>
            <td class="spark">
              <svg width="60" height="22" viewBox="0 0 60 22" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
                <path d="${sparkPath(c.d7)}" stroke="${c.d7 >= 0 ? '#16c784' : '#ea3943'}" stroke-width="2" stroke-linecap="round"/>
              </svg>
            </td>
          </tr>`;
      }).join('');
    }

    function renderPagination() {
      const pages = [1,2,3,4,84];
      pagination.innerHTML = pages.map(p => `<button class="page-btn ${p===activePage?'active':''}" data-page="${p}">${p}</button>`).join('') + '<span class="mono" style="padding-left:8px;color:#667085">…</span>';
      pagination.querySelectorAll('[data-page]').forEach(btn => {
        btn.addEventListener('click', () => {
          activePage = Number(btn.dataset.page);
          pagination.querySelectorAll('.page-btn').forEach(b => b.classList.remove('active'));
          btn.classList.add('active');
          renderTable();
        });
      });
    }

    categoryTabs.addEventListener('click', (e) => {
      const btn = e.target.closest('[data-category]');
      if (!btn) return;
      activeCategory = btn.dataset.category;
      categoryTabs.querySelectorAll('.tab').forEach(t => t.classList.toggle('active', t === btn));
      activeCategoryLabel.textContent = activeCategory;
      renderTable();
    });

    networkTabs.addEventListener('click', (e) => {
      const btn = e.target.closest('[data-network]');
      if (!btn) return;
      activeNetwork = btn.dataset.network;
      networkTabs.querySelectorAll('.tab').forEach(t => t.classList.toggle('active', t === btn));
      activeNetworkLabel.textContent = activeNetwork;
      renderTable();
    });

    document.getElementById('columnsToggle').addEventListener('click', () => {
      document.getElementById('columnsPanel').classList.toggle('show');
    });

    document.getElementById('filtersToggle').addEventListener('click', () => {
      document.getElementById('filtersPanel').classList.toggle('show');
    });

    document.querySelectorAll('#columnsPanel input[type="checkbox"]').forEach(chk => {
      chk.addEventListener('change', () => {
        document.querySelectorAll('.col-' + chk.dataset.col).forEach(cell => {
          cell.style.display = chk.checked ? '' : 'none';
        });
      });
    });

    document.getElementById('readMore').addEventListener('click', (e) => {
      const more = document.getElementById('moreSummary');
      const isOpen = more.classList.toggle('show');
      e.target.textContent = isOpen ? 'Read Less' : 'Read More';
    });

    const slides = Array.from(document.querySelectorAll('.slide'));
    let slideIndex = 0;
    function showSlide(i) {
      slideIndex = (i + slides.length) % slides.length;
      slides.forEach((s, idx) => s.classList.toggle('active', idx === slideIndex));
    }
    document.getElementById('prevSlide').addEventListener('click', () => showSlide(slideIndex - 1));
    document.getElementById('nextSlide').addEventListener('click', () => showSlide(slideIndex + 1));
    setInterval(() => showSlide(slideIndex + 1), 6000);

    renderTable();
    renderPagination();
  </script>
